import React from "react"
import { graphql, useStaticQuery } from "gatsby"

export const CoreSkills = () => {
  const data = useStaticQuery(graphql`
    query CoreSkillsQuery {
      allCoreSkillsJson {
        nodes {
          category
          skills
        }
      }
    }
  `)

  const skillCategories = data.allCoreSkillsJson.nodes

  return (
    <section className="pt-6 flex border-t border-t-8 print:!border-t-1 border-gray-400">
      <div className="print:w-full">
        <h2 className="text-3xl hover:text-green-500">Core Skills</h2>
        <ul className="mt-4 space-y-2">
          {skillCategories.map(item => (
            <li key={item.category}>
              <strong className="text-gray-700 text-sm">
                {item.category}:
              </strong>{" "}
              <span className="text-gray-600 text-sm">{item.skills}</span>
            </li>
          ))}
        </ul>
      </div>
    </section>
  )
}
