import React from "react"
import { graphql, useStaticQuery } from "gatsby"
import {
  DetailSection,
  ExperienceItem,
  Paragraph,
  Stack,
} from "./ExperienceItem"
import { ToolsIcons } from "../icons"
import DevIcon from "../dev-icon/dev-icon"

export const Experience = () => {
  const data = useStaticQuery(graphql`
    query ExperienceQuery {
      allExperienceJson {
        nodes {
          companyName
          initialYear
          finalYear
          paragraph
          details {
            paragraph
          }
          stack
          projects {
            companyName
            paragraph
            paragraphHtml
            stack
          }
        }
      }
    }
  `)

  const experiences = data.allExperienceJson.nodes

  return (
    <section className="pt-6 flex border-t border-t-8 print:!border-t-1 border-gray-400">
      <div className="w-2/3 print:w-full">
        <h2 className="text-3xl hover:text-green-500">Experience</h2>
        {experiences.map((experience, index) => (
          <ExperienceItem
            key={index}
            companyName={experience.companyName}
            initialYear={experience.initialYear}
            finalYear={experience.finalYear}
          >
            <Paragraph>{experience.paragraph}</Paragraph>
            {(experience.details?.length > 0 ||
              experience.projects?.length > 0 ||
              experience.stack) && (
              <DetailSection>
                {experience.details?.map((detail, detailIndex) => (
                  <Paragraph key={detailIndex}>{detail.paragraph}</Paragraph>
                ))}
                {experience.stack && <Stack>{experience.stack}</Stack>}
                {experience.projects?.map((project, projectIndex) => (
                  <ExperienceItem
                    key={projectIndex}
                    companyName={project.companyName}
                    showDates={false}
                  >
                    {project.paragraphHtml ? (
                      <Paragraph>
                        <span
                          dangerouslySetInnerHTML={{
                            __html: project.paragraphHtml,
                          }}
                        />
                      </Paragraph>
                    ) : (
                      <Paragraph>{project.paragraph}</Paragraph>
                    )}
                    {project.stack && <Stack>{project.stack}</Stack>}
                  </ExperienceItem>
                ))}
              </DetailSection>
            )}
          </ExperienceItem>
        ))}
      </div>
      <div className="w-1/3 print:hidden">
        <h2 className="text-3xl hover:text-green-500 pl-6">Tools</h2>
        <div className="flex flex-row flex-wrap gap-4 px-3">
          {ToolsIcons.map(item => (
            <DevIcon key={item.name} name={item.name} icon={item.icon} />
          ))}
        </div>
      </div>
    </section>
  )
}
