const GLITCH_CHARS = "!@#$%^&*()_+-=[]{}|;:,.<>?/~`01"

const useGlitchText = (finalText, delay = 0, speed = 30) => {
  const [display, setDisplay] = useState("")
  useEffect(() => {
    let timeout
    let interval
    let currentIndex = 0

    timeout = setTimeout(() => {
      interval = setInterval(() => {
        if (currentIndex <= finalText.length) {
          const revealed = finalText.slice(0, currentIndex)
          const scrambled = Array.from(
            { length: Math.min(3, finalText.length - currentIndex) },
            () => GLITCH_CHARS[Math.floor(Math.random() * GLITCH_CHARS.length)]
          ).join("")
          setDisplay(revealed + scrambled)
          currentIndex++
        } else {
          setDisplay(finalText)
          clearInterval(interval)
        }
      }, speed)
    }, delay)

    return () => {
      clearTimeout(timeout)
      clearInterval(interval)
    }
  }, [finalText, delay, speed])

  return display
}

const HexGrid = () => {
  const canvasRef = useRef(null)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext("2d")
    let animationId
    let time = 0

    const resize = () => {
      canvas.width = window.innerWidth
      canvas.height = window.innerHeight
    }
    resize()
    window.addEventListener("resize", resize)

    const draw = () => {
      time += 0.003
      ctx.clearRect(0, 0, canvas.width, canvas.height)

      const size = 40
      const h = size * Math.sqrt(3)
      const cols = Math.ceil(canvas.width / (size * 3)) + 2
      const rows = Math.ceil(canvas.height / h) + 2

      for (let row = -1; row < rows; row++) {
        for (let col = -1; col < cols; col++) {
          const x = col * size * 3 + (row % 2) * size * 1.5
          const y = row * h * 0.5

          const dist = Math.sqrt(
            Math.pow(x - canvas.width / 2, 2) +
              Math.pow(y - canvas.height / 2, 2)
          )
          const wave = Math.sin(dist * 0.005 - time * 2) * 0.5 + 0.5
          const alpha = wave * 0.08

          ctx.beginPath()
          for (let i = 0; i < 6; i++) {
            const angle = (Math.PI / 3) * i - Math.PI / 6
            const hx = x + size * 0.4 * Math.cos(angle)
            const hy = y + size * 0.4 * Math.sin(angle)
            if (i === 0) ctx.moveTo(hx, hy)
            else ctx.lineTo(hx, hy)
          }
          ctx.closePath()
          ctx.strokeStyle = `rgba(0, 255, 200, ${alpha})`
          ctx.lineWidth = 0.5
          ctx.stroke()
        }
      }

      // Scanning line
      const scanY = ((time * 80) % (canvas.height + 200)) - 100
      const gradient = ctx.createLinearGradient(0, scanY - 50, 0, scanY + 50)
      gradient.addColorStop(0, "rgba(0, 255, 200, 0)")
      gradient.addColorStop(0.5, "rgba(0, 255, 200, 0.06)")
      gradient.addColorStop(1, "rgba(0, 255, 200, 0)")
      ctx.fillStyle = gradient
      ctx.fillRect(0, scanY - 50, canvas.width, 100)

      animationId = requestAnimationFrame(draw)
    }

    draw()

    return () => {
      window.removeEventListener("resize", resize)
      cancelAnimationFrame(animationId)
    }
  }, [])

  return <canvas ref={canvasRef} className="sf-hex-grid" />
}

const TimelineNode = ({ company, period, stack, index, isActive, onClick }) => (
  <div
    className={`sf-timeline-node ${isActive ? "sf-active" : ""}`}
    style={{ animationDelay: `${1.5 + index * 0.2}s` }}
    onClick={onClick}
    role="button"
    tabIndex={0}
    onKeyDown={e => e.key === "Enter" && onClick()}
  >
    <div className="sf-node-marker">
      <div className="sf-node-ring" />
      <div className="sf-node-dot" />
    </div>
    <div className="sf-node-content">
      <h3 className="sf-company">{company}</h3>
      <span className="sf-period">{period}</span>
      {stack && <p className="sf-stack">{stack}</p>}
    </div>
  </div>
)

const SkillBar = ({ category, skills, index }) => (
  <div
    className="sf-skill-row"
    style={{ animationDelay: `${2 + index * 0.15}s` }}
  >
    <div className="sf-skill-label">{category}</div>
    <div className="sf-skill-value">{skills}</div>
    <div className="sf-skill-bar-track">
      <div
        className="sf-skill-bar-fill"
        style={{ animationDelay: `${2.5 + index * 0.15}s` }}
      />
    </div>
  </div>
)

